from docx import Document
from docx.shared import Pt
import re
for p in ["农业机械装备生产实习报告.docx","农工综合生产实习报告.docx"]:
    d=Document(p)
    n=sum(len(re.sub(r'\s','',x.text)) for x in d.paragraphs)
    for t in d.tables:
        for r in t.rows:
            for c in r.cells: n+=len(re.sub(r'\s','',c.text))
    # 抽查正文字号
    sizes={}
    for para in d.paragraphs:
        for r in para.runs:
            if r.font.size: sizes[r.font.size.pt]=sizes.get(r.font.size.pt,0)+len(r.text)
    print("="*50)
    print(p)
    print("  字符数:",n," 图片:",len(d.inline_shapes)," 表格:",len(d.tables)," 段落:",len(d.paragraphs))
    print("  字号分布(按字符数):",dict(sorted(sizes.items(),key=lambda x:-x[1])[:5]))
    print("  节:",[ (s.page_width.cm, s.left_margin.cm, s.right_margin.cm) for s in d.sections])
